import { useState } from "react";
import { Icon } from "../components/icons";

interface Props {
  onClose: () => void;
  onScan: () => void;
  onSubmit: (input: string) => Promise<void>;
}

/**
 * Replaces the design mock's static `AVAILABLE` issuer catalog (which had no backend
 * equivalent — there is no "browse issuers" endpoint) with the real redemption flow: an issuer
 * hands the holder a pre-authorized code or an `openid-credential-offer://` URI (generated by
 * the issuer console's own OID4VCI offer screen), which this wallet redeems via
 * `POST /api/v1/wallets/{id}/claim`.
 */
export function AddCredentialOverlay({ onClose, onScan, onSubmit }: Props) {
  const [input, setInput] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const submit = async () => {
    if (!input.trim()) return;
    setSubmitting(true);
    setError(null);
    try {
      await onSubmit(input.trim());
    } catch {
      setError("That code couldn't be redeemed. Check it and try again.");
      setSubmitting(false);
    }
  };

  return (
    <div className="idt-overlay">
      <div className="idt-ovheader">
        <button className="idt-iconbtn" aria-label="Close" onClick={onClose}><Icon name="close" size={18} /></button>
        <div className="idt-ovtitle">Add credential</div>
        <div style={{ width: 40 }} />
      </div>
      <div className="idt-view">
        <div className="idt-detail-body">
          <p style={{ color: "var(--muted)", fontSize: 13.5 }}>
            Scan the QR code or paste the offer link an issuer gave you to redeem a credential into this wallet.
          </p>

          <button className="idt-setrow" onClick={onScan} style={{ marginTop: 16 }}>
            <span className="idt-setrow__ico"><Icon name="scan" size={17} /></span>
            <span className="idt-setrow__txt"><span className="k">Scan issuer QR code</span></span>
            <Icon name="chevR" size={16} />
          </button>

          <div className="idt-attr-group">
            <div className="lbl">Or paste offer link / code</div>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="openid-credential-offer://... or a pre-authorized code"
              rows={4}
              style={{ width: "100%", padding: 12, border: "1px solid var(--line)", borderRadius: 8, fontSize: 13.5, fontFamily: "var(--font-mono)", resize: "vertical" }}
            />
          </div>

          {error && <div className="idt-error">{error}</div>}
        </div>
        <div className="idt-scroll-pad" />
      </div>
      <div className="idt-btnbar">
        <button className="idt-btn idt-btn--primary" onClick={submit} disabled={!input.trim() || submitting}>
          {submitting ? "Redeeming…" : "Redeem credential"}
        </button>
      </div>
    </div>
  );
}
